add_action('rest_api_init', function() {
  register_rest_route('fsurgery/v1', '/read', array(
    'methods' => 'GET',
    'permission_callback' => function() { return current_user_can('manage_options'); },
    'callback' => function($req) {
      $out = array();
      $pid = intval($req->get_param('post'));
      if ($pid) {
        $out['meta'] = array();
        foreach (get_post_meta($pid) as $k => $v) { $out['meta'][$k] = maybe_unserialize($v[0]); }
        $out['post'] = array('post_type' => get_post_type($pid), 'status' => get_post_status($pid));
      }
      $wo = get_option('woodmart_options');
      if (is_array($wo)) {
        $out['wd_opts'] = array();
        foreach ($wo as $k => $v) { if (preg_match('/footer|prefooter|header_/i', $k)) $out['wd_opts'][$k] = $v; }
      } else { $out['wd_opts_type'] = gettype($wo); }
      $theme = get_option('stylesheet');
      $out['stylesheet'] = $theme;
      $mods = get_option('theme_mods_' . $theme);
      if (is_array($mods)) {
        $out['theme_mods_keys'] = array_keys($mods);
      }
      global $wpdb;
      $out['opt_rows'] = $wpdb->get_results("SELECT option_name, LENGTH(option_value) AS len FROM {$wpdb->options} WHERE option_name LIKE '%footer%' OR option_name LIKE '%prefooter%' OR option_name LIKE '%woodmart%' LIMIT 100");
      $out['sidebars'] = wp_get_sidebars_widgets();
      return $out;
    }
  ));
});
